create table public.category (
  id integer generated by default as identity primary key,
  title text not null,
  description text not null default ''
);

create table public.car (
  id integer generated by default as identity primary key,
  title text not null,
  short_title text not null,
  description text not null default '',
  category_id integer not null references public.category(id) on delete restrict,
  price numeric(10,2) not null check (price > 0),
  image text not null default '',
  specs jsonb,
  features text[] not null default '{}'
);

create index car_category_id_idx on public.car(category_id);

alter table public.category enable row level security;
alter table public.car enable row level security;

-- Catálogo público somente leitura: sem policies de escrita, INSERT/UPDATE/DELETE ficam negados.
create policy "category_select_public" on public.category for select to anon, authenticated using (true);
create policy "car_select_public" on public.car for select to anon, authenticated using (true);

revoke insert, update, delete, truncate on public.category, public.car from anon, authenticated;

